<?php require __DIR__.'/app.php';render_header('Đơn hàng của tôi');?>
<section class="page-heading"><span class="eyebrow">TÀI KHOẢN CỦA BẠN</span><h1>Đơn hàng của tôi</h1><p>Xin chào <?=e(user()['name'])?>. Theo dõi trạng thái và đánh giá sản phẩm sau khi nhận hàng.</p></section><?php if(!$orders):?><div class="empty-state">Bạn chưa có đơn hàng nào. <a href="index.php?page=sanpham">Bắt đầu mua sắm</a></div><?php else:?><section class="order-list" aria-label="Danh sách đơn hàng"><?php foreach($orders as $o):$state=$o['status'];$steps=['pending','confirmed','shipping','completed'];$stepIndex=array_search($state,$steps,true);?>
<article class="order-card" id="don-<?=(int)$o['id']?>"><div class="order-card-top"><div><span class="order-label">Mã đơn hàng</span><strong class="order-number">#<?=(int)$o['id']?></strong></div><span class="status-pill <?=e(lopTrangThaiDonHang($state))?>"><?=e(nhanTrangThaiDonHang($state))?></span></div><div class="order-meta"><span>Ngày đặt: <b><?=e(date('d/m/Y H:i',strtotime($o['created_at'])))?></b></span><span>Phí giao hàng: <b><?=((float)($o['shipping_fee']??0))>0?money($o['shipping_fee']):'Miễn phí'?></b></span><span>Tổng tiền: <b class="order-total"><?=money($o['total'])?></b></span></div>
<?php if($state==='cancelled'):?><div class="order-cancel-note">Đơn hàng đã được hủy.</div><?php else:?><div class="order-progress" aria-label="Tiến độ đơn hàng"><?php foreach($steps as $i=>$step):$class=$i<(int)$stepIndex?'done':($i===(int)$stepIndex?'current':'');?> <div class="progress-step <?=$class?>"><span><?=$i<(int)$stepIndex?'✓':($i+1)?></span><small><?=e(nhanTrangThaiDonHang($step))?></small></div><?php endforeach;?></div><?php endif;?>
<div class="order-card-actions"><?php if($state==='pending'):?><form method="post" action="index.php?page=huy_don" data-confirm="Bạn có chắc chắn muốn hủy đơn hàng này không? Sau khi hủy, bạn sẽ không thể khôi phục đơn hàng." data-confirm-title="Xác nhận hủy đơn hàng" data-confirm-accept="Hủy đơn hàng"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><button class="button button-cancel-order" type="submit">Hủy đơn hàng</button></form><?php endif;?><a class="button button-dark" href="index.php?page=thanhtoan&id=<?=(int)$o['id']?>">Xem chi tiết đơn hàng</a></div>
<?php if($state==='completed'&&!empty($o['review_products'])):?><section class="order-review-section"><div class="order-review-heading"><h2>Đánh giá sản phẩm</h2><p>Chia sẻ trải nghiệm sau khi nhận hàng. Đánh giá sẽ hiển thị ở trang quản trị.</p></div><div class="order-review-list"><?php foreach($o['review_products'] as $reviewProduct):?><article class="order-review-item"><img src="<?=e(image_url($reviewProduct))?>" alt="<?=e($reviewProduct['name'])?>" loading="lazy"><div class="order-review-product"><b><?=e($reviewProduct['name'])?></b><small>Số lượng đã mua: <?=(int)$reviewProduct['quantity']?></small></div><form class="order-review-form" method="post" action="index.php?page=gui_danhgia"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=(int)$o['id']?>"><input type="hidden" name="product_id" value="<?=(int)$reviewProduct['product_id']?>"><label>Đánh giá<select name="stars" required><?php for($star=5;$star>=1;$star--):?><option value="<?=$star?>" <?=(int)($reviewProduct['stars']??5)===$star?'selected':''?>><?=$star?> sao</option><?php endfor;?></select></label><label class="order-review-comment">Nhận xét<textarea name="comment" rows="2" maxlength="2000" required placeholder="Sản phẩm thế nào? Hãy chia sẻ với mọi người..."><?=e($reviewProduct['comment']??'')?></textarea></label><button class="button button-dark" type="submit"><?=!empty($reviewProduct['stars'])?'Cập nhật đánh giá':'Gửi đánh giá'?></button></form></article><?php endforeach;?></div></section><?php endif;?></article><?php endforeach;?></section><?php endif;?><?php render_footer();?>

